    const pagesDataInScope =
      !options.basePath || hasBasePath(pagesDataUrl.pathname, options.basePath);
    if (pagesDataInScope) {
      pagesDataUrl.pathname = stripBasePath(pagesDataUrl.pathname, options.basePath);
    }
