function releaseMiddlewareRequestBody(
  request: NextRequest,
  waitUntilPromises: Promise<unknown>[],
  retainedByResponse = false,
): void {
  const body = request.body;
  if (!body || retainedByResponse) return;

  const cancel = () => {
    if (!body.locked) {
      void body.cancel().catch(() => {});
